<template>
  <div>
    <embed :src="url" type="application/pdf" width="100%" height="800px" />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import axios from 'axios';
import { DOC2API_URL } from 'src/pages/APIs';

export default defineComponent({
  data() {
    return {
      url: ref(''),
    };
  },
  async mounted() {
    await this.getFile();
  },
  methods: {
    async getFile() {
      try {
        const org_id = this.$route.params.org_id as string;
        if (org_id) {
          const response = await axios.get(
            `${DOC2API_URL}/supplier/get_terms_and_conditions?org_id=${org_id}`,
            {
              responseType: 'blob',
            },
          );
          if (response) {
            this.url = window.URL.createObjectURL(response.data);
          }
        }
      } catch (error) {
        logError('Failed to fetch file:', error);
      }
    },
  },
});
</script>
